"""Stage 91: the source reference (docs/57, generated by tools/analyze_source_docs.py from src/c) is current, and the sources are documented: every file starts with a comment that says what it is, every function declared in a
header and every structure and enumeration has a comment, every `Name $ADDR` comment is the address of that label in src/asm/pacman.s, and the algorithm table names functions and Python twins that exist."""
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_source_docs as D  # noqa: E402


class SourceDocs(unittest.TestCase):
    def test_every_file_declaration_and_structure_is_documented(self):
        nofile, nodecl, wrong = D.gaps()
        self.assertEqual(nofile, [], "files that do not start with a comment")
        self.assertEqual(nodecl, [], "declarations or structures without a comment")
        self.assertEqual(wrong, [], "comments naming a wrong ROM address")

    def test_the_comments_with_addresses_are_many_and_all_checked(self):
        fn = D.functions()
        lab = D.asm_labels()
        named = [x for x in fn if x[5]]
        self.assertGreaterEqual(len(named), 60)
        self.assertGreaterEqual(sum(1 for x in named if x[5] in lab), 50)

    def test_the_algorithm_table_names_things_that_exist(self):
        alltext = "".join(D.read(p) for m, f, p in D.files())
        for a, cf, tw, ch in D.ALGORITHMS:
            for c in cf.split(","):
                self.assertRegex(alltext, r"\b" + c.strip() + r"\s*\(", c)
            for t in tw.split(","):
                self.assertTrue(os.path.exists(os.path.join(ROOT, "tools", t.strip())), t)

    def test_every_module_has_a_folder_and_every_folder_a_module(self):
        folders = {d for d in os.listdir(D.SRC) if os.path.isdir(os.path.join(D.SRC, d))}
        self.assertEqual(folders, {m for m, _, _ in D.MODULES})

    def test_every_python_tool_and_test_starts_with_a_docstring(self):
        """the Python side of the source (tools/, tests/) says what each file is: a module docstring (found missing in one helper in stage 91)"""
        import ast
        import glob
        missing = []
        for p in sorted(glob.glob(os.path.join(ROOT, "tools", "*.py")) + glob.glob(os.path.join(ROOT, "tests", "*.py"))):
            with open(p, encoding="utf-8") as fh:
                if not ast.get_docstring(ast.parse(fh.read())):
                    missing.append(os.path.relpath(p, ROOT))
        self.assertEqual(missing, [])

    def test_the_chapter_is_current(self):
        with open(os.path.join(ROOT, "docs", "57-source-code-reference.md"), encoding="utf-8", newline="") as fh:
            have = fh.read()
        self.assertEqual(have.replace("\r\n", "\n"), D.doc(), "regenerate: python -I tools/analyze_source_docs.py --doc docs/57-source-code-reference.md")


if __name__ == "__main__":
    unittest.main()
